import{_ as c,l as i,o as e,c as l,v as r,p as o,x as s,d as n,i as u,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"校验与 scrub","description":"","frontmatter":{"title":"校验与 scrub","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fs-checksum-scrub.md","filePath":"cs/fs-checksum-scrub.md","lastUpdated":1789023840000}'),p={name:"cs/fs-checksum-scrub.md"};function h(m,a,E,b,f,C){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="校验与-scrub" tabindex="-1">校验与 scrub <a class="header-anchor" href="#校验与-scrub" aria-label="Permalink to &quot;校验与 scrub&quot;">​</a></h1><div class="epigraph"><p>每个块带校验和，读时核对；scrub 在空闲时把整池读一遍，把静默损坏变成可修复事件。</p><footer>—— 据 Bonwick and Moore 对 ZFS end-to-end checksum 的论述；Bairavasundaram et al. 对磁盘静默错误的测量</footer></div><p><a href="/cs/cow-filesystem">上一课</a>让树根原子切换，但块从设备回来时可能已经静默翻比特。SCSI/NVMe 的 ECC 停在设备内部；文件系统若只信「读成功」，用户看到的是错数据。<a href="/cs/page-cache">页缓存</a> 也会把错页当成真。缺口是 <strong>端到端校验 + scrub</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静默损坏（bit rot、错误扇区被重映射成全零、固件写错位）不会总变成 I/O 错误。ZFS 把 checksum 放进父指针（或块头），读路径比较；不匹配则从镜像/RAID 副本修复，再写回。btrfs 同样在树里存校验。缺口不是再讲 COW，而是：校验存在哪、何时算、scrub 如何遍历所有已分配块而不经用户读。</p><p>本课不把加密当校验——<a href="/cs/dm-crypt">dm-crypt</a> 是后课存储栈。</p><p><span class="marginnote">校验算法是 Fletcher、CRC32C 或 SHA 家族的工程选择。对象是「父节点提交了子块的摘要」。scrub 与 fsck 不同：前者验证内容，后者验证结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：数据下盘前算摘要，COW 父结点时写入。读：设备返回后先核对再进页缓存；失败则走冗余。scrub：从根遍历（或沿分配位图）发出读，统计错误，能修则修。与 ext4 的 metadata_csum 对照：ext4 可校验元数据，数据校验不是默认主路径；ZFS/btrfs 把数据也纳入。</p>',9)),(e(),o(d,null,{default:s(()=>[u(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E8%AF%BB%E5%9D%97%22%5D%20--%3E%20CK%5B%22%E6%A0%B8%E5%AF%B9%E7%88%B6%E8%AE%B0%E5%BD%95%E7%9A%84%E6%91%98%E8%A6%81%22%5D%0A%20%20CK%20--%3E%7C%22%E5%8C%B9%E9%85%8D%22%7C%20CACHE%5B%22%E8%BF%9B%E5%85%A5%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20CK%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20REPAIR%5B%22%E5%89%AF%E6%9C%AC%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20SCRUB%5B%22scrub%20%E9%81%8D%E5%8E%86%22%5D%20--%3E%20RD%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>端到端校验把「磁盘说 OK」从信任基里拿掉一层：文件系统知道块应该是什么。COW 很关键——原地改同一块会让校验更新与数据写交织出窗口；新块新摘要随新父结点提交。不要把本课写成网络的 CRC 课：这里的损坏来自存储介质与路径，不是以太网帧。</p><p>与 <a href="/cs/ext4-journal">日志</a> 分工：日志防的是崩溃半更新；scrub 防的是已提交块日后腐烂。</p><p>实现上：校验和必须存在父指针里才能端到端：只存在块头则替换整块可以对上自校验。scrub 与用户读路径共用核对，差别是遍历顺序与优先级，不是另一套哈希。 读法上只引用<a href="/cs/cow-filesystem">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>校验与 scrub</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入自我修复的全部 RAID 形状，不保证单盘无冗余时 checksum 失败还能救——那时只能报错。下一课用同一套 COW 根做快照与克隆：校验保证历史切面读回来仍对。</p><p>版本字段会变，课序钉的是机制对象「校验与 scrub」，不是某一主线内核的结构体名。 后课默认：已提交块可以带着摘要被巡检。命名一个历史根并共享未改块，下一课快照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>校验在父指针里；读路径核对。</li><li>scrub 主动遍历，结构检查仍是 fsck 的事。</li><li>快照与克隆是下一课的缺口。</li><li>出处：ZFS 校验设计；Bairavasundaram et al.；btrfs checksum 文档。</li></ul>',11))])}const B=c(p,[["render",h]]);export{A as __pageData,B as default};
